from itertools import zip_longest


def _normalize(version):
    values = [int(part) for part in version.split('.')]
    while values and values[-1] == 0:
        values.pop()
    return values


def newer(a, b):
    left = _normalize(a)
    right = _normalize(b)
    for a_part, b_part in zip_longest(left, right, fillvalue=0):
        if a_part != b_part:
            return a_part > b_part
    return False
